  var seq = Number(id & 4095n);
  var worker = Number((id >> 12n) & 31n);
  var dc = Number((id >> 17n) & 31n);
  var ts = Number((id >> 22n) & 0x1FFFFFFFFFFn) + epoch;
  return { timestamp: ts, datacenter: dc, worker: worker, sequence: seq };
